reference_patch.text:
diff --git a/fs/nfsd/auth.c b/fs/nfsd/auth.c
index f650e475d8f0d84af1bb3013b6b35ef77421cde2..fdf2aad7347090b7ceecd97a5a9eb3dfdfc1093a 100644
--- a/fs/nfsd/auth.c
+++ b/fs/nfsd/auth.c
@@ -60,10 +60,10 @@ int nfsd_setuser(struct svc_rqst *rqstp, struct svc_export *exp)
 				gi->gid[i] = exp->ex_anon_gid;
 			else
 				gi->gid[i] = rqgi->gid[i];
-
-			/* Each thread allocates its own gi, no race */
-			groups_sort(gi);
 		}
+
+		/* Each thread allocates its own gi, no race */
+		groups_sort(gi);
 	} else {
 		gi = get_group_info(rqgi);
 	}

